// Vigía Orbital – static site. All numbers come from site/data/*.json,
// generated by scripts/build_site_data.py from the official model run.
const COLORS = {"Low": "#2E9E6A", "Moderate": "#E8C547", "High": "#F08A24", "Very high": "#D9481C", "Extreme": "#A51F1F"};
const TEXT_ON = {"Moderate": "#3a2f00"};
const S = {mode: "latest", canton: "CR501", day: 0, data: {}, meta: null, layer: null};

const fmtDay = (iso, opts) => new Date(iso + "T00:00:00Z").toLocaleDateString("en-US", {timeZone: "UTC", ...opts});
const dowDay = iso => fmtDay(iso, {weekday: "short"}) + " " + fmtDay(iso, {day: "numeric"});
const pct = p => (p < 0.01 ? "<1" : Math.round(p * 100)) + " %";
const pill = lvl => `<span class="pill" style="background:${COLORS[lvl]};color:${TEXT_ON[lvl] || "#fff"}">${lvl}</span>`;

async function load() {
  const get = f => fetch("data/" + f).then(r => r.json());
  const [geo, latest, demo, meta] = await Promise.all([get("cantons.geojson"), get("latest.json"), get("demo.json"), get("meta.json")]);
  S.data = {latest, demo}; S.meta = meta;
  await tryLiveApi();
  initMap(geo); renderLegend(); renderMetrics();
  document.getElementById("m-latest").onclick = () => setMode("latest");
  document.getElementById("m-demo").onclick = () => setMode("demo");
  const q = new URLSearchParams(location.search);
  setMode(q.get("mode") === "demo" ? "demo" : "latest");
}

// If an API is configured, the "Latest" view is computed live by FastAPI; otherwise the static file is used.
async function tryLiveApi() {
  const api = (window.VIGIA_API || "").replace(/\/$/, "");
  if (!api) return;
  try {
    const r = await fetch(api + "/forecast/all", {signal: AbortSignal.timeout(30000)});
    if (!r.ok) throw new Error(r.status);
    const j = await r.json(), cantons = {};
    if (S.data.latest && j.eve < S.data.latest.eve) throw new Error("API forecast older than the saved one");
    for (const c of j.cantons) cantons[c.canton_id] = {name: c.canton, eve: c.eve, days: c.days, conditions: c.conditions};
    S.data.latest = {eve: j.eve, cantons, inputs: j.inputs};
    S.live = api;
  } catch (e) { console.warn("Live API unavailable, using static forecast", e); }
}

function initMap(geo) {
  const map = L.map("map", {zoomSnap: 0.25, attributionControl: true});
  L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",
    {maxZoom: 12, opacity: 0.55, attribution: "© OpenStreetMap contributors · boundaries: geoBoundaries"}).addTo(map);
  S.layer = L.geoJSON(geo, {
    style: () => ({weight: 1.2, color: "#0F2236", fillOpacity: 0.45}),
    onEachFeature: (f, l) => {
      l.on("click", () => { S.canton = f.properties.canton_id; render(); });
      l.bindTooltip("", {sticky: true});
    }
  }).addTo(map);
  map.fitBounds(S.layer.getBounds(), {padding: [10, 10]});
}

function setMode(m) {
  S.mode = m;
  S.day = m === "demo" ? 4 : 0;
  if (m === "demo") S.canton = "CR501";
  for (const id of ["latest", "demo"]) document.getElementById("m-" + id).setAttribute("aria-selected", id === m);
  render();
}

function render() {
  const D = S.data[S.mode], eve = D.eve;
  const sel = D.cantons[S.canton];
  const day = sel.days[S.day];
  document.getElementById("issued").textContent =
    `Issued on the evening of ${fmtDay(eve, {weekday: "long", day: "numeric", month: "long", year: "numeric"})} · map shows ${fmtDay(day.date, {weekday: "long", day: "numeric", month: "short"})}`;
  document.getElementById("note").innerHTML = S.mode === "demo"
    ? "Demo: a real past week. The model used here was trained <b>without any 2018 data</b>, so this is an honest back-test. ✓ = fire detected by satellite that day."
    : S.live && !D.inputs
      ? `<b>Live:</b> computed just now by the <a href="${S.live}/docs">Vigía Orbital API</a> (FastAPI).`
    : S.live
      ? `<b>Live:</b> computed just now by the <a href="${S.live}/docs">Vigía Orbital API</a> (FastAPI) with the newest NASA data. ` +
        `Fire detections (NASA FIRMS, VIIRS NOAA-20): through ${fmtDay(D.inputs.recent_fire_through, {day: "numeric", month: "short"})}. ` +
        `Weather (NASA POWER, published a few days late): ${fmtDay(D.inputs.weather_as_of, {day: "numeric", month: "short"})}. ` +
        `Vegetation (MODIS composites): ${fmtDay(D.inputs.ndmi_composite || D.inputs.ndvi_composite, {day: "numeric", month: "short"})}.`
      : `Saved forecast, issued ${fmtDay(D.eve, {day: "numeric", month: "short"})} (refreshed every morning; the live API is asleep or out of date right now).` +
        (D.inputs && D.inputs.recent_fire_through ? ` Fire detections through ${fmtDay(D.inputs.recent_fire_through, {day: "numeric", month: "short"})}; weather from ${fmtDay(D.inputs.weather_as_of, {day: "numeric", month: "short"})}.` : "");

  S.layer.eachLayer(l => {
    const c = D.cantons[l.feature.properties.canton_id];
    if (!c) { l.setStyle({fillColor: "#ccc"}); return; }
    const d = c.days[S.day];
    l.setStyle({fillColor: COLORS[d.level], weight: l.feature.properties.canton_id === S.canton ? 3.5 : 1.2});
    l.setTooltipContent(`<b>${l.feature.properties.name}</b><br>${d.level} · ${pct(d.prob)}${d.fire_observed ? " · fire ✓" : ""}`);
    if (l.feature.properties.canton_id === S.canton) l.bringToFront();
  });

  const name = S.layer.getLayers().find(l => l.feature.properties.canton_id === S.canton).feature.properties.name;
  document.getElementById("cname").textContent = name;
  document.getElementById("csub").textContent = "Chance of at least one satellite-detected vegetation fire in the canton, per day";
  document.getElementById("days").innerHTML = sel.days.map((d, i) => `
    <button class="day${i === S.day ? " sel" : ""}" data-i="${i}" aria-pressed="${i === S.day}">
      <div class="dow">${dowDay(d.date)}</div>
      ${pill(d.level)}<div class="p">${pct(d.prob)}</div>
      ${S.mode === "demo" ? `<div class="obs">${d.fire_observed ? "fire ✓" : "no fire"}</div>` : ""}
    </button>`).join("");
  document.querySelectorAll(".day").forEach(b => b.onclick = () => { S.day = +b.dataset.i; render(); });

  document.getElementById("dlabel").textContent = "· " + dowDay(day.date) + " " + fmtDay(day.date, {month: "short"});
  const drv = [["Weather", day.x_weather], ["Vegetation", day.x_vegetation], ["Recent fire", day.x_recent_fire]];
  document.getElementById("drivers").innerHTML =
    `<p class="normal">Normal for this week: <b>${pct(day.normal_prob)}</b> → forecast: <b>${pct(day.prob)}</b> ${pill(day.level)}</p>` +
    drv.map(([n, x]) => {
      const w = Math.min(Math.abs(Math.log2(x)), 1) * 50;            // ×0.5 … ×2 spans half the bar
      const up = x >= 1;
      return `<div class="drv"><span>${n}</span><div class="bar"><div class="mid"></div>
        <div class="fill" style="${up ? "left:50%" : `left:${50 - w}%`};width:${w}%;background:${up ? "#E4571B" : "#2F6FB0"}"></div></div>
        <b title="multiplies the odds">×${x.toFixed(2)}</b></div>`;
    }).join("") +
    `<p class="muted">Each factor multiplies the odds of fire: above ×1 raises the risk (orange), below ×1 lowers it (blue).</p>`;

  document.getElementById("cdate").textContent = "· " + fmtDay(sel.conditions.date || D.eve, {weekday: "short", day: "numeric", month: "short", year: "numeric"});
  const c = sel.conditions, v = (x, u = "") => x == null ? "–" : x + u;
  document.getElementById("cond").innerHTML = [
    ["Max temp", v(c.t_max_c, " °C")], ["Min temp", v(c.t_min_c, " °C")], ["Humidity", v(c.humidity_pct, " %")], ["Wind", v(c.wind_kmh, " km/h")],
    ["Rain", v(c.rain_mm, " mm")], ["Days without rain", v(c.days_without_rain)], ["NDVI (greenness)", v(c.ndvi)], ["NDMI (moisture)", v(c.ndmi)]
  ].map(([k, x]) => `<div><small>${k}</small><b>${x}</b></div>`).join("");
}

function renderLegend() {
  document.getElementById("legend").innerHTML = S.meta.levels.map(([u, n], i, a) =>
    `<span><i style="background:${COLORS[n]}"></i>${n} (${i ? Math.round(a[i - 1][0] * 100) : 0}${u > 1 ? "+ %" : "–" + Math.round(u * 100) + " %"})</span>`).join("");
}

function renderMetrics() {
  const m = S.meta.metrics;
  document.getElementById("metrics").innerHTML = [
    [m.auc_model_2013_2025.toFixed(3), "AUC (climatology " + m.auc_ref_2013_2025.toFixed(3) + ")"],
    ["+" + (m.bss_2013_2025 * 100).toFixed(1) + " %", "Brier skill vs climatology"],
    [m.years_bss_positive, "seasons with positive skill"]
  ].map(([b, s]) => `<div><b>${b}</b><small>${s}</small></div>`).join("") +
    `<div style="grid-column:1/-1"><small>Skill by lead day: ${Object.entries(m.lead_bss).map(([k, x]) => `day ${k} +${(x * 100).toFixed(1)} %`).join(" · ")}</small></div>`;
  document.getElementById("runid").textContent = S.meta.run_id;
}

load();
